-- Real parts for Solar Builder.
-- Generated by catalog/emit_sql.py from web/catalog.json. Do not hand-edit.
--
-- The app reads these eight tables through its catalog server function,
-- so nothing in src/ has to change. Safe to re-run.

BEGIN;

-- Visitor drafts reference the demo part ids. They are fictional, and the
-- rows below replace them, so the drafts go first rather than block the
-- delete with a foreign key error. Checklist rows follow via ON DELETE
-- CASCADE from saved_builds.
DELETE FROM public.checklist_items;
DELETE FROM public.saved_builds;

-- CEC publishes no warranty figure for solar modules. The column is
-- NOT NULL and our source has no value, so relax it rather than invent
-- one. The app does not read this field.
ALTER TABLE public.panels ALTER COLUMN warranty_years DROP NOT NULL;

-- The household the demo starts from
ON CONFLICT (household_id) DO UPDATE SET name = excluded.name, location = excluded.location, timezone = excluded.timezone, monthly_consumption_kwh = excluded.monthly_consumption_kwh, budget_php = excluded.budget_php, system_type = excluded.system_type, critical_load_kw = excluded.critical_load_kw, target_backup_hours = excluded.target_backup_hours, tariff_php_per_kwh = excluded.tariff_php_per_kwh, peak_sun_hours = excluded.peak_sun_hours, performance_ratio = excluded.performance_ratio, is_synthetic = excluded.is_synthetic;


-- 61 panels
ON CONFLICT (panel_id) DO UPDATE SET name = excluded.name, rated_power_w = excluded.rated_power_w, vmp_v = excluded.vmp_v, imp_a = excluded.imp_a, voc_v = excluded.voc_v, isc_a = excluded.isc_a, warranty_years = excluded.warranty_years;


-- Hybrid inverters, 230 V
ON CONFLICT (inverter_id) DO UPDATE SET name = excluded.name, system_type = excluded.system_type, rated_ac_power_kw = excluded.rated_ac_power_kw, max_pv_power_kw = excluded.max_pv_power_kw, mppt_min_v = excluded.mppt_min_v, mppt_max_v = excluded.mppt_max_v, max_dc_voltage_v = excluded.max_dc_voltage_v, max_mppt_current_a = excluded.max_mppt_current_a, max_mppt_isc_a = excluded.max_mppt_isc_a, mppt_count = excluded.mppt_count, battery_min_v = excluded.battery_min_v, battery_max_v = excluded.battery_max_v, max_battery_power_kw = excluded.max_battery_power_kw, bms_family = excluded.bms_family, monitoring_support = excluded.monitoring_support;


-- Battery
ON CONFLICT (battery_id) DO UPDATE SET name = excluded.name, nominal_capacity_kwh = excluded.nominal_capacity_kwh, nominal_voltage_v = excluded.nominal_voltage_v, min_operating_voltage_v = excluded.min_operating_voltage_v, max_operating_voltage_v = excluded.max_operating_voltage_v, max_charge_discharge_kw = excluded.max_charge_discharge_kw, max_parallel_units = excluded.max_parallel_units, bms_family = excluded.bms_family;


-- The demo offers reference the demo shops. Remove the offers first,
-- or the foreign key blocks removing the shops.
DELETE FROM public.listings WHERE supplier_id IN ('S1','S2');
DELETE FROM public.suppliers WHERE supplier_id IN ('S1','S2');

-- Shop
ON CONFLICT (supplier_id) DO UPDATE SET name = excluded.name, location = excluded.location, is_synthetic = excluded.is_synthetic;


-- 66 offers — every part in this file, so nothing reads 'No stock available'. is_synthetic = true; replace with real quotes.
ON CONFLICT (listing_id) DO UPDATE SET component_id = excluded.component_id, component_type = excluded.component_type, supplier_id = excluded.supplier_id, unit_price_php = excluded.unit_price_php, stock_units = excluded.stock_units, price_as_of = excluded.price_as_of, is_synthetic = excluded.is_synthetic;


-- Presets. C2 is the build page's default.
ON CONFLICT (configuration_id) DO UPDATE SET household_id = excluded.household_id, name = excluded.name, panel_id = excluded.panel_id, panel_count = excluded.panel_count, inverter_id = excluded.inverter_id, battery_id = excluded.battery_id, battery_count = excluded.battery_count, series_panels_per_string = excluded.series_panels_per_string, parallel_strings_per_mppt = excluded.parallel_strings_per_mppt, used_mppt_count = excluded.used_mppt_count, other_cost_allowance_php = excluded.other_cost_allowance_php, status = excluded.status;


-- What the monitoring page simulates from.
ON CONFLICT (system_id) DO UPDATE SET household_id = excluded.household_id, configuration_id = excluded.configuration_id, panel_capacity_kw = excluded.panel_capacity_kw, inverter_capacity_kw = excluded.inverter_capacity_kw, battery_capacity_kwh = excluded.battery_capacity_kwh, battery_min_soc_pct = excluded.battery_min_soc_pct, battery_max_soc_pct = excluded.battery_max_soc_pct, initial_soc_pct = excluded.initial_soc_pct, solar_dc_to_bus_efficiency = excluded.solar_dc_to_bus_efficiency, battery_charge_efficiency = excluded.battery_charge_efficiency, battery_discharge_efficiency = excluded.battery_discharge_efficiency, source = excluded.source;


-- Now nothing refers to the fictional demo parts.
DELETE FROM public.panels WHERE panel_id IN ('P550','P450');
DELETE FROM public.inverters WHERE inverter_id IN ('I5000','I3000');
DELETE FROM public.batteries WHERE battery_id IN ('B512','BHV');
DELETE FROM public.suppliers WHERE supplier_id IN ('S1','S2');

COMMIT;

-- ---------------------------------------------------------------------
-- Ran it? Then the SQL Editor shows this table straight away.
-- Expect: panels 61 · inverters 4 · batteries 1 · configurations 3 · suppliers 1 · listings 66
-- ---------------------------------------------------------------------
SELECT 'batteries' AS table_name, count(*) AS rows FROM public.batteries
UNION ALL SELECT 'configurations', count(*) FROM public.configurations
UNION ALL SELECT 'inverters', count(*) FROM public.inverters
UNION ALL SELECT 'listings', count(*) FROM public.listings
UNION ALL SELECT 'panels', count(*) FROM public.panels
UNION ALL SELECT 'suppliers', count(*) FROM public.suppliers
ORDER BY table_name;